const data = $input.first().json;

const errors = [];
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const requesterEmail = String(data['Your e-mail'] || '').trim().toLowerCase();
const targetEmail = String(data['Target e-mail'] || '').trim().toLowerCase();
const workflowInput = String(data['Workflow ID'] || '').trim();

function extractWorkflowId(value) {
  if (!value) return '';

  // Full n8n URL, example:
  // https://n8n.example.com/workflow/a1B2c3D4e5F6g7H8
  const match = value.match(/\/workflow\/([^/?#]+)/);

  if (match && match[1]) {
    return match[1];
  }

  // If user pasted only the ID
  return value;
}

const workflowId = extractWorkflowId(workflowInput);

if (!emailRegex.test(requesterEmail)) {
  errors.push('Invalid requester email');
}

if (!emailRegex.test(targetEmail)) {
  errors.push('Invalid target email');
}

if (!workflowId || workflowId.length < 5) {
  errors.push('Workflow ID looks wrong');
}

if (requesterEmail === targetEmail) {
  errors.push('You cannot share with yourself');
}

if (errors.length > 0) {
  throw new Error(errors.join('; '));
}

return [
  {
    json: {
      requester_email: requesterEmail,
      target_email: targetEmail,
      workflow_id: workflowId,
      workflow_url_raw: workflowInput,
      submittedAt: data.submittedAt,
      formMode: data.formMode
    }
  }
];

const workflowData = $input.first().json;
const formData = $('Form Validation Node').first().json;

const requesterEmail = String(formData.requester_email).trim().toLowerCase();

const ownerShare = Array.isArray(workflowData.shared)
  ? workflowData.shared.find(s => s.role === 'workflow:owner')
  : null;

if (!ownerShare) {
  throw new Error('Could not find workflow owner entry');
}

const ownerProject = ownerShare.project || {};
const ownerProjectName = String(ownerProject.name || '').toLowerCase();
const ownerProjectType = ownerProject.type || null;

if (ownerProjectType !== 'personal') {
  throw new Error('This workflow is in a project, not a personal workspace. Use normal project sharing.');
}

if (!ownerProjectName.includes(requesterEmail)) {
  throw new Error(`You are not the owner of this workflow. Owner project is: ${ownerProject.name}`);
}

return [
  {
    json: {
      requester_email: formData.requester_email,
      target_email: formData.target_email,
      workflow_id: formData.workflow_id,
      workflow_name: workflowData.name,
      owner_confirmed: true,
      owner_project_id: ownerShare.projectId,
      owner_project_name: ownerProject.name,
      owner_project_type: ownerProject.type
    }
  }
];

const response = $input.first().json;
const formData = $('Validate ownership').first().json;

const users = Array.isArray(response.data) ? response.data : [];

const targetEmail = String(formData.target_email).trim().toLowerCase();

const targetUser = users.find(user =>
  String(user.email || '').trim().toLowerCase() === targetEmail
);

if (!targetUser) {
  throw new Error(`Target user not found in n8n: ${formData.target_email}`);
}

return [
  {
    json: {
      ...formData,
      target_user_id: targetUser.id,
      target_user_email: targetUser.email,
      target_user_first_name: targetUser.firstName || null,
      target_user_last_name: targetUser.lastName || null
    }
  }
];

const response = $input.first().json;
const formData = $('Validate Target User').first().json;
const workflowData = $('HTTP Request to n8n API - get workflow').first().json;

const projects = Array.isArray(response.data) ? response.data : [];

const targetEmail = String(formData.target_email).trim().toLowerCase();

const targetProject = projects.find(project => {
  const name = String(project.name || '').toLowerCase();
  const type = String(project.type || '').toLowerCase();

  return type === 'personal' && name.includes(targetEmail);
});

if (!targetProject) {
  throw new Error(`Target personal project not found for: ${formData.target_email}`);
}

// Existing shares, excluding the owner.
// Important because PUT /share probably replaces the share list, not only appends.
const existingSharedProjectIds = Array.isArray(workflowData.shared)
  ? workflowData.shared
      .filter(s => s.role !== 'workflow:owner')
      .map(s => s.projectId)
      .filter(Boolean)
  : [];

const shareWithIds = [...new Set([
  ...existingSharedProjectIds,
  targetProject.id
])];

return [
  {
    json: {
      ...formData,
      target_project_id: targetProject.id,
      target_project_name: targetProject.name,
      target_project_type: targetProject.type,
      share_with_ids: shareWithIds
    }
  }
];

const workflowData = $('HTTP Request to n8n API - get workflow').first().json;
const formData = $('Find target personal project').first().json;

const cleanWorkflow = {
  name: `${workflowData.name} - copy for ${formData.target_user_first_name || formData.target_email}`,
  nodes: workflowData.nodes || [],
  connections: workflowData.connections || {},
  settings: {}
};

return [
  {
    json: {
      ...formData,
      workflow_copy_body: cleanWorkflow
    }
  }
];
